  SELECT DISTINCT ON (sd.deal_id) sd.deal_id, s.cT,s.cA,s.dT,s.dA,s.iT,s.iA,s.rT,s.rA,s.net
  FROM src s
  JOIN staffing_deals sd ON LOWER(TRIM(sd.deal_id)) = LOWER(TRIM(s.csv_id))
  ORDER BY sd.deal_id, s.cT DESC
)
