matched AS (
  SELECT DISTINCT ON (sd.deal_id) sd.deal_id, s.cA, s.iA, s.rA, s.net
  FROM src s
  JOIN staffing_deals sd ON LOWER(TRIM(sd.deal_id)) = LOWER(TRIM(s.csv_id))
  ORDER BY sd.deal_id, s.cA DESC
)
, del AS (
  DELETE FROM deal_financials WHERE month=DATE '2026-04-01' AND deal_id IN (SELECT deal_id FROM matched) RETURNING 1
)
